from jsonb_array_elements($cards$[["svc-host-sequence-0001","service","host-sequence",1,["host"],"order","Put the host's steps in order, from opening the desk to seating guests.",null,["Seat guests","Set up host desk","Hand menus","Welcome","Acknowledgement","Return to host desk"],["Set up host desk","Acknowledgement","Welcome","Seat guests","Hand menus","Return to host desk"],"Set up the desk, acknowledge the guest, welcome them, seat them, hand menus, then go straight back to the desk.","Every guest gets the same warm start, however busy the door is.",false,"SOS Host (Sequence of Service, Host), steps 1 to 6",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0002","service","host-sequence",1,["host"],"scenario","You're helping a guest at the desk when a couple walks in. What do you do?",null,["Smile and let them know you've seen them","Finish with your guest, then look up","Ask a waiter to seat them","Point them to the waiting area"],["Smile and let them know you've seen them"],"Give every guest immediate acknowledgement with a warm smile, even while you're attending to someone else.","A guest who knows they've been seen will wait happily.",false,"SOS Host (Sequence of Service, Host), step 2; Service Training Program v2026/01, sequence step 1",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0003","service","host-sequence",1,["host","server"],"mcq","A regular, Mr Khan, arrives for breakfast. How do you welcome him?",null,["\"Good morning, welcome back Mr Khan\"","\"Good morning, table for one?\"","\"Hi, have you been here before?\"","\"Good morning, are you waiting for someone?\""],["\"Good morning, welcome back Mr Khan\""],"If guests have been before, greet them by name: \"welcome back Mr X\".","Using a regular's name makes them feel at home, which is why they keep coming back.",false,"SOS Host (Sequence of Service, Host), step 3; Service Training Program v2026/01, guest service standards",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0004","service","host-sequence",1,["host"],"mcq","Which table should you choose for arriving guests?",null,["The best table for their group size and type","The table nearest the door","Whichever table was cleared most recently","A table in the busiest section"],["The best table for their group size and type"],"Take guests to the best table for their group size and type, for example families or business guests, and seat tables evenly through the restaurant.","Seating evenly stops one waiter being overloaded, so every table gets good service.",false,"SOS Host (Sequence of Service, Host), step 4",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0005","service","host-sequence",1,["host"],"scenario","One waiter's section is full and another is quiet. A family of four arrives. Where do you seat them?",null,["A suitable table in the quieter section","In the full section, near the kitchen","At the bar until the full section clears","Wherever the family points first"],["A suitable table in the quieter section"],"Seat tables evenly through the restaurant, choosing a table that suits a family of four.","An overloaded waiter means slower service for everyone in that section.",false,"SOS Host (Sequence of Service, Host), step 4 tip",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0006","service","host-sequence",1,["host"],"mcq","Guests are seated. What do you say as you hand over the menus?",null,["\"Your waiter will be along shortly\"","\"Let me know when you're ready to order\"","\"The kitchen is busy today\"","\"Do you know what you'd like?\""],["\"Your waiter will be along shortly\""],"Hand open menus to the seated guests and tell them their waiter will be along shortly.","Guests relax when they know what happens next.",false,"SOS Host (Sequence of Service, Host), step 5",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0007","service","host-sequence",1,["host"],"multi","A family with a toddler sits down. What can you offer as you hand menus? Pick all that apply.",null,["A highchair","A children's menu","A colouring sheet","The wine list","A dessert menu"],["A highchair","A children's menu","A colouring sheet"],"Give any highchairs needed, plus a children's menu and a colouring sheet.","Settling the children first lets the whole family enjoy the visit.",false,"SOS Host (Sequence of Service, Host), step 5",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0008","service","host-sequence",1,["host"],"mcq","The restaurant is full and guests are waiting. What should you do?",null,["Give a realistic waiting time and use a waiting list","Promise a table in five minutes","Ask them to come back later","Seat them at a table that isn't ready"],["Give a realistic waiting time and use a waiting list"],"When it's busy, be realistic about waiting times and keep a waiting list.","An honest wait is easier for guests than a broken promise.",false,"SOS Host (Sequence of Service, Host), step 6",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0009","service","host-sequence",1,["host"],"mcq","How do you answer the restaurant phone?",null,["\"Good afternoon, Maison Mathis Arabian Ranches, this is Sara speaking\"","\"Hello, Maison Mathis?\"","\"Maison Mathis, please hold\"","\"Hi, who's calling?\""],["\"Good afternoon, Maison Mathis Arabian Ranches, this is Sara speaking\""],"Greet with the time of day, Maison Mathis and the location name, then your own name, and ask \"How can I help you?\"","The phone is often a guest's first contact with the house.",false,"SOS Host (Sequence of Service, Host), step 7",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0010","service","host-sequence",1,["host"],"mcq","A guest calls to book a table. What do you do with their details?",null,["Ask their name, write the details down and repeat them back","Remember them and enter them later","Ask them to book online instead","Write down the time only"],["Ask their name, write the details down and repeat them back"],"Ask the guest's name, take the details, write them down and repeat them back, then thank them for calling.","Repeating details back catches mistakes before the guest arrives.",false,"SOS Host (Sequence of Service, Host), step 7",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0011","service","host-sequence",1,["host"],"mcq","The phone rings while you're with a guest at the desk. What's right?",null,["Excuse yourself politely and answer it","Let it ring until you've finished","Answer without a word to the guest","Ask the guest to answer it"],["Excuse yourself politely and answer it"],"If you're attending a guest when the phone rings, excuse yourself to answer it.","Both guests feel looked after: the one in front of you and the one calling.",false,"SOS Host (Sequence of Service, Host), step 7 tip",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0012","service","host-sequence",1,["host"],"multi","Setting up the host desk: what do you check? Pick all that apply.",null,["Today's reservations, with booked tables assigned","Menus stocked, with specials and promo menus","The waiting area and front entrance are clean","The coffee machine pressure","The bar's spirit levels"],["Today's reservations, with booked tables assigned","Menus stocked, with specials and promo menus","The waiting area and front entrance are clean"],"Check the reservations diary and assign booked tables, stock menus with specials and promo menus, and check the entrance and waiting area as a guest would see them.","The door is the guest's first impression of the house.",false,"SOS Host (Sequence of Service, Host), step 1",null,"live","David","2026-10-16",null,1],["svc-host-sequence-0013","service","host-sequence",1,["host"],"mcq","Why does the host check the toilets often?",null,["Guests link toilet cleanliness with our kitchens","Because the cleaners finish at noon","To count how many guests are inside","It's only needed before closing"],["Guests link toilet cleanliness with our kitchens"],"Check the toilets often: guests associate their cleanliness with the cleanliness of our kitchens.","A clean bathroom tells guests they can trust the food.",false,"SOS Host (Sequence of Service, Host), step 6 tip",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0014","service","waiter-sequence",1,["server"],"order","Put the waiter's steps in order.",null,["Clearing","Drinks order and delivery","Bill payment and goodbye","Welcome and seating","Desserts and coffees","Food delivery and check back","Food order and punch"],["Welcome and seating","Drinks order and delivery","Food order and punch","Food delivery and check back","Clearing","Desserts and coffees","Bill payment and goodbye"],"Welcome, drinks, food order, food delivery and check back, clearing, desserts and coffees, then bill and goodbye.","Following the same order every time means nothing is forgotten when it's busy.",false,"SOS Waiter (Sequence of Service, Waiter), steps 1 to 7",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0015","service","waiter-sequence",1,["server","runner","bar","barista"],"mcq","Guests walk in and the host is busy. Who welcomes them?",null,["Whoever sees them first","Only the host","The manager on duty","The waiter whose section it is, once free"],["Whoever sees them first"],"Don't rely on the host to welcome guests: it is everyone's responsibility.","Every guest should be acknowledged within 30 seconds, whoever is nearest.",false,"SOS Waiter (Sequence of Service, Waiter), step 1 tip; Service Training Program v2026/01, sequence step 1",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0016","service","waiter-sequence",1,["server"],"mcq","Taking the drinks order, what else do you tell guests?",null,["Today's specials and anything out of stock","How long the food will take","The price of each drink","Which tables are free"],["Today's specials and anything out of stock"],"Ask \"can I get you something to drink?\" and tell guests about daily specials and any out-of-stock items.","Guests shouldn't fall for a dish, then hear it's not available.",false,"SOS Waiter (Sequence of Service, Waiter), step 2; Service Training Program v2026/01, sequence step 2",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0017","service","waiter-sequence",1,["server"],"mcq","A table orders soft drinks. What do you also suggest?",null,["Bottled water","A second round straight away","A cocktail each","Nothing more"],["Bottled water"],"Suggest bottled water to every table, whatever else they order, offering still or sparkling.","Water arrives first and keeps guests comfortable while they wait for food.",false,"SOS Waiter (Sequence of Service, Waiter), step 2 tip; Service Training Program v2026/01, sequence step 2",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0018","service","waiter-sequence",1,["server"],"mcq","You've punched a food order. What do you take to the table straight away?",null,["The bread tin","The dessert menu","The bill wallet","Extra napkins"],["The bread tin"],"Repeat the order back, punch it straight away and take the bread tin to the table. Bread is served within 5 minutes of the order.","Fresh bread is part of the house welcome and fills the wait for starters.",false,"SOS Waiter (Sequence of Service, Waiter), step 3; Service Training Program v2026/01, sequence step 4",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0019","service","waiter-sequence",1,["server"],"mcq","When you take the food order, what must you ask every table?",null,["Whether anyone has an allergy","Whether they're celebrating","How they heard of us","If they want the bill"],["Whether anyone has an allergy"],"At the food order, ask \"does anyone have any allergies?\" If they do, tell the head chef straightaway. Never guess.","Asking every time is how we catch an allergy before the food is cooked.",true,"SOS Waiter (Sequence of Service, Waiter), step 3 (allergen line added 16 Oct 2026); Service Training Program v2026/01, sequence step 4",null,"review","David","2026-10-16",null,1],["svc-waiter-sequence-0020","service","waiter-sequence",1,["server"],"scenario","A guest orders the Steak and Fries 200 gr. How do you suggest a side?",null,["\"Would you like Crispy Truffle Fries or a Garden Salad with that?\"","\"Any sides?\"","\"Our sides are on the back page\"","Say nothing, it comes with fries"],["\"Would you like Crispy Truffle Fries or a Garden Salad with that?\""],"Suggest side dishes by name to complement the main. Knowing the sides list makes this easy.","A named suggestion helps the guest picture it, so it's easier to say yes.",false,"SOS Waiter (Sequence of Service, Waiter), step 3 tip; AR lunch and dinner menu, Sides",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0021","service","waiter-sequence",1,["server"],"mcq","What do you ask when you check back?",null,["\"How are you enjoying your meal?\"","\"Is everything OK?\" as you walk past","\"Are you finished?\"","\"Ready for the bill?\""],["\"How are you enjoying your meal?\""],"Check the food arrived correctly with condiments, then check back after a few bites and ask how they're enjoying it.","Catching a problem early prevents a complaint and protects our reviews.",false,"SOS Waiter (Sequence of Service, Waiter), step 4; Service Training Program v2026/01, check-back protocol",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0022","service","waiter-sequence",1,["server","runner"],"multi","When you check back on a table, what else do you do? Pick all that apply.",null,["Offer more drinks","Remove empty glasses","Present the bill","Clear plates still being eaten from"],["Offer more drinks","Remove empty glasses"],"At the check back, offer more drinks and remove any empty glasses.","An empty glass is a missed chance to look after the guest.",false,"SOS Waiter (Sequence of Service, Waiter), step 4 tip",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0023","service","waiter-sequence",1,["server","runner"],"scenario","One guest has pushed their plate aside; the others are still eating. What do you do?",null,["Remove that plate","Wait until everyone has finished","Clear every plate","Ask the table if they're done"],["Remove that plate"],"Clear when everyone has finished, but if someone pushes their plate to the side first, you can remove it.","The guest has signalled they're done, and the table stays tidy.",false,"SOS Waiter (Sequence of Service, Waiter), step 5 tip",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0024","service","waiter-sequence",1,["server"],"mcq","A guest has food left and says it was lovely. What do you offer?",null,["To pack the leftovers for them","A smaller portion next time","A discount","To leave the plate"],["To pack the leftovers for them"],"After asking \"how was everything?\", clear the plates and pack any leftovers for the guest.","They take the meal home and remember us later.",false,"SOS Waiter (Sequence of Service, Waiter), step 5",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0025","service","waiter-sequence",1,["server"],"mcq","Mains are cleared. How do you start desserts?",null,["A dessert menu each, your favourite, and offer coffees","Ask \"any dessert?\" with the bill","Wait for guests to ask","Bring one dessert menu for the table"],["A dessert menu each, your favourite, and offer coffees"],"Hand a dessert menu to each guest, say \"my favourite dessert is the...\" and offer coffees.","A personal recommendation is the friendliest way to suggest dessert.",false,"SOS Waiter (Sequence of Service, Waiter), step 6",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0026","service","waiter-sequence",1,["server"],"mcq","A table says they're too full for dessert. What could you suggest?",null,["Visiting our bakery counter","A smaller main next time","Nothing at all","A second round of mains"],["Visiting our bakery counter"],"Invite guests to visit the bakery counter for more cakes and desserts.","Takeaway from the bakery lets them enjoy it later.",false,"SOS Waiter (Sequence of Service, Waiter), step 6 tip; Operations Manual v2026/01, bakery takeaway",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0027","service","waiter-sequence",1,["server"],"mcq","When should the bill be ready?",null,["Checked and ready as soon as the table asks","Printed when the mains arrive","Only after the guest asks twice","When the next booking arrives"],["Checked and ready as soon as the table asks"],"Watch tables close to finishing, check their bill details and present it in a bill wallet as soon as they ask.","Waiting for the bill is one of the commonest reasons for a slow-service complaint.",false,"SOS Waiter (Sequence of Service, Waiter), step 7; Service Training Program v2026/01, sequence step 6",null,"live","David","2026-10-16",null,1],["svc-waiter-sequence-0028","service","waiter-sequence",1,["server","host","runner","bar","barista"],"mcq","When does a guest stop being our guest?",null,["When they leave","When they pay","When they finish eating","When the bill is printed"],["When they leave"],"Guests are our guests until they leave, not only until they pay. Thank them and say \"see you again soon\".","A warm goodbye is as important as a warm welcome.",false,"SOS Waiter (Sequence of Service, Waiter), step 7 tip; Service Training Program v2026/01, sequence step 6",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0029","service","runner-sequence",1,["runner"],"order","Put the food runner's steps in order.",null,["Serve food","Return to food pass","Food pass set up","Offer condiments","Run food to table","Check KOTs and prepare tray","Check order is complete"],["Food pass set up","Check KOTs and prepare tray","Run food to table","Serve food","Offer condiments","Check order is complete","Return to food pass"],"Set up the pass, check the KOT and prepare the tray, run, serve, offer condiments, check the order is complete, then return to the pass.","The same routine every run means the right food reaches the right guest, hot.",false,"SOS Food Runner (Sequence of Service, Food Runner), steps 1 to 7",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0030","service","runner-sequence",1,["runner"],"mcq","As you load a tray, what do you check against the KOT?",null,["Each dish, plus any spoons or steak knives needed","Only the main courses","The table number only","The price of each item"],["Each dish, plus any spoons or steak knives needed"],"Check off each item on the KOT as it goes on the tray, including spoons or steak knives.","A missing knife or side means the guest waits while others eat.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 2",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0031","service","runner-sequence",1,["runner"],"scenario","A table of six is ready and you can't carry it all. What do you do?",null,["Get someone to help so it goes in one go","Take half now and half later","Leave it until a waiter comes","Take the largest plates first"],["Get someone to help so it goes in one go"],"Take the whole table's order in one go. If you can't, get someone else to help you.","Guests at one table should eat together.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 2",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0032","service","runner-sequence",1,["runner"],"mcq","Before a dish leaves the pass, what do you check?",null,["It's garnished correctly","The guest's name","That the plate is full to the edge","The bill total"],["It's garnished correctly"],"Check every dish is garnished correctly before taking it from the pass.","The plate the guest sees should match the house standard every time.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 2 tip",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0033","service","runner-sequence",1,["runner","server"],"multi","Serving at the table: what's right? Pick all that apply.",null,["Announce each dish as you serve it","Move around the table to each guest","Warn guests about hot plates","Reach across guests to save time","Ask the table who ordered what"],["Announce each dish as you serve it","Move around the table to each guest","Warn guests about hot plates"],"Announce each dish, move around the table rather than reaching over anyone, and warn about hot plates, keeping them away from children.","Guests feel looked after, and nobody gets burnt.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 4; Service Training Program v2026/01, sequence step 5",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0034","service","runner-sequence",1,["runner","server"],"scenario","You drop a plate on the way to the table. What do you do?",null,["Get it replaced as a priority and tell your manager","Serve the rest and say nothing","Ask the guest to reorder","Wait for the next table's order first"],["Get it replaced as a priority and tell your manager"],"If food is dropped or spilled, replace it as a priority and inform your manager.","The guest is already waiting; quick action keeps the delay short.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 6 tip",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0035","service","runner-sequence",1,["runner"],"mcq","A guest asks you for another drink. What do you do?",null,["Tell their waiter straight away","Say you're only the runner","Bring it on your next run","Ask them to wave to the bar"],["Tell their waiter straight away"],"If guests order more drinks, inform the relevant waiter immediately.","The guest asked once; they shouldn't need to ask again.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 7",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0036","service","runner-sequence",1,["runner","server"],"mcq","Walking back to the pass from a table, what should be in your hands?",null,["Any empty glasses, plates or cutlery","Nothing, to move faster","Only your tray","The next KOT"],["Any empty glasses, plates or cutlery"],"Never leave a table empty-handed: remove any empty glasses, plates or cutlery.","Every trip keeps tables tidy without extra journeys.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 7 tip",null,"live","David","2026-10-16",null,1],["svc-runner-sequence-0037","service","runner-sequence",1,["runner"],"mcq","A guest tells you their dish is too salty. Who do you tell?",null,["The chef in charge, and the waiter","No one, it's a one-off","Only the next guest","The host"],["The chef in charge, and the waiter"],"Liaise with the chef in charge and pass on any guest feedback about dishes.","The kitchen can only fix what it hears about.",false,"SOS Food Runner (Sequence of Service, Food Runner), step 1 tip; Service Training Program v2026/01, guest recovery",null,"live","David","2026-10-16",null,1],["svc-barista-sequence-0038","service","barista-sequence",1,["barista"],"order","Put the barista's steps in order.",null,["Prepare orders","Restock","Turn on equipment and set up","Check KOTs","Serving drinks","Coffee quality check"],["Turn on equipment and set up","Coffee quality check","Check KOTs","Prepare orders","Serving drinks","Restock"],"Set up, check the coffee quality, check KOTs, prepare, serve, then restock.","A set routine keeps every cup to standard through the rush.",false,"SOS Barista (Sequence of Service, Barista), steps 1 to 6",null,"live","David","2026-10-16",null,1],["svc-barista-sequence-0039","service","barista-sequence",1,["barista"],"mcq","Before extracting a coffee, how long do you purge water from the group head?",null,["2 seconds","10 seconds","30 seconds","No purge needed"],["2 seconds"],"Release or purge water for 2 seconds from the group head before extracting coffee.","A clean, stable group head gives a better-tasting shot.",false,"SOS Barista (Sequence of Service, Barista), step 2 tip",null,"live","David","2026-10-16",null,1],["svc-barista-sequence-0040","service","barista-sequence",1,["barista"],"mcq","You have a cappuccino and a latte to make. Which first, where possible?",null,["The cappuccino, to use the foam","The latte, it's quicker","Whichever is cheaper","Both at once with one jug"],["The cappuccino, to use the foam"],"Where possible, make cappuccinos before lattes so the foam gets used.","Less waste, and both drinks get the right milk texture.",false,"SOS Barista (Sequence of Service, Barista), step 4 tip",null,"live","David","2026-10-16",null,1],["svc-barista-sequence-0041","service","barista-sequence",1,["barista"],"mcq","Several KOTs print at once. In what order do you make them?",null,["In the order received, reading ahead","Easiest drinks first","Biggest table first","Takeaway first"],["In the order received, reading ahead"],"Prepare orders in the order received, and read ahead to make several checks at once.","First come, first served is fair, and reading ahead saves time.",false,"SOS Barista (Sequence of Service, Barista), step 3",null,"live","David","2026-10-16",null,1],["svc-barista-sequence-0042","service","barista-sequence",1,["barista"],"scenario","Two lattes are ready and no waiter has come for them. What do you do?",null,["Let the waiters know politely, or run them yourself","Leave them until a waiter passes","Remake them when someone comes","Call the guest to the bar"],["Let the waiters know politely, or run them yourself"],"Serve hot drinks immediately: let the waiters know politely, or run them yourself whenever possible.","Coffee that sits goes cold and comes back to be remade.",false,"SOS Barista (Sequence of Service, Barista), step 5",null,"live","David","2026-10-16",null,1],["svc-barista-sequence-0043","service","barista-sequence",1,["barista"],"multi","Setting up the coffee station: what do you do? Pick all that apply.",null,["Check machine pressure and temperature","Warm the cups and glassware","Make a test espresso and check the flow","Have spare printer rolls ready","Pre-pour milk into jugs for the day"],["Check machine pressure and temperature","Warm the cups and glassware","Make a test espresso and check the flow","Have spare printer rolls ready"],"Turn on and check pressure and temperature, warm cups, calibrate with a test espresso, and keep spare printer rolls ready.","Getting set up right before the first order keeps the rush smooth.",false,"SOS Barista (Sequence of Service, Barista), steps 1 to 3; Operations Manual v2026/01, espresso calibration",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0044","service","timing-standards",1,["host","server","runner","bar","barista"],"mcq","How quickly must every guest be acknowledged on arrival?",null,["Within 30 seconds","Within 2 minutes","Within 5 minutes","Once they're seated"],["Within 30 seconds"],"Every guest is acknowledged within 30 seconds of arrival, with eye contact and a smile.","A guest who knows they've been seen will wait happily.",false,"Service Training Program v2026/01, key timing standards",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0045","service","timing-standards",1,["server","host","runner","bar"],"mcq","How soon after seating should water be served?",null,["Within 3 minutes","Within 10 minutes","With the food","Only when asked"],["Within 3 minutes"],"Offer still or sparkling water on seating; water is served within 3 minutes.","Water first makes guests comfortable straight away.",false,"Service Training Program v2026/01, key timing standards",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0046","service","timing-standards",1,["server","host","runner","bar"],"mcq","What's the standard for serving a cocktail after it's ordered?",null,["Within 8 minutes","Within 3 minutes","Within 15 minutes","With the starters"],["Within 8 minutes"],"Other drinks are served within 5 minutes; cocktails take up to 8 minutes.","Drinks set the pace for the whole meal.",false,"Service Training Program v2026/01, key timing standards",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0047","service","timing-standards",1,["server","host","runner","bar"],"mcq","How soon after arrival should the food order be taken?",null,["Within 10 minutes","Within 3 minutes","Within 20 minutes","When guests call you over"],["Within 10 minutes"],"Take the food order within 10 minutes of arrival.","Guests notice a slow start more than almost anything else.",false,"Service Training Program v2026/01, key timing standards",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0048","service","timing-standards",1,["server","host","runner","bar"],"mcq","Starters are ordered. How long until they should be served?",null,["Within 15 minutes","Within 5 minutes","Within 25 minutes","Within 30 minutes"],["Within 15 minutes"],"Starters are served within 15 minutes.","Knowing the standard helps you spot a delay early.",false,"Service Training Program v2026/01, key timing standards",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0049","service","timing-standards",1,["server","host","runner","bar"],"scenario","A table ordered mains only, no starters. When should the mains arrive?",null,["Within 20 minutes","Within 10 minutes","Within 15 minutes","Within 30 minutes"],["Within 20 minutes"],"Mains come 10 minutes after starters are cleared, or within 20 minutes when there are no starters.","You can update the guest honestly if the kitchen is running late.",false,"Service Training Program v2026/01, key timing standards",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0050","service","timing-standards",1,["server","host","runner","bar"],"mcq","Food has just been served. When do you check back?",null,["Within 2 minutes","Within 10 minutes","When the plates are empty","Only if the guest looks unhappy"],["Within 2 minutes"],"Check back within 2 minutes of the food being served.","If there's a problem, two minutes in is early enough to fix it.",false,"Service Training Program v2026/01, key timing standards; Operations Manual v2026/01, check-backs",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0051","service","timing-standards",1,["server"],"mcq","A guest asks for the bill. What are the standards?",null,["Present it within 3 minutes, payment done within 5","Present it within 10 minutes","Bring it with dessert","Payment done within 15 minutes"],["Present it within 3 minutes, payment done within 5"],"Present the bill within 3 minutes of the request and finalise payment within 5.","The last minutes of a visit shape how guests remember it.",false,"Service Training Program v2026/01, sequence step 6",null,"live","David","2026-10-16",null,1],["svc-timing-standards-0052","service","timing-standards",1,["server","host","runner","bar"],"order","Put these in the order they should happen for a table.",null,["Food order taken","Water served","Check back","Bread served"],["Water served","Food order taken","Bread served","Check back"],"Water within 3 minutes, food order within 10, bread within 5 minutes of the order, then check back 2 minutes after food is served.","Each step sets up the next one, so the meal flows.",false,"Service Training Program v2026/01, key timing standards",null,"live","David","2026-10-16",null,1],["sop-allergen-protocol-0001","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"scenario","A guest says, \"I have a severe nut allergy.\" What do you do first?",null,["Tell the head chef immediately","Point to the dishes without (N)","Suggest the salads","Note it on the bill"],["Tell the head chef immediately"],"If a guest declares an allergy, inform the head chef immediately. Never guess; always verify.","An allergy can be life-threatening, and only the kitchen knows every ingredient.",true,"Service Training Program v2026/01, allergen protocol",null,"review","David","2026-10-16",null,1],["sop-allergen-protocol-0002","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"mcq","How must every allergen request be treated?",null,["As life-critical","As a preference","As a special request if the kitchen is quiet","As the guest's own responsibility"],["As life-critical"],"Treat every allergen request as life-critical, and as medical, not a service issue. No shortcuts.","One mistake can put a guest in hospital.",true,"Service Training Program v2026/01, allergen protocol; Operations Manual v2026/01, allergen management",null,"review","David","2026-10-16",null,1],["sop-allergen-protocol-0003","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"scenario","A guest with a nut allergy asks about a dish with no (N) on the menu. What do you say?",null,["\"Let me check with the head chef for you\"","\"It's nut-free, there's no (N)\"","\"I think it's fine\"","\"Most of our dishes are safe\""],["\"Let me check with the head chef for you\""],"Never guess on allergens: always verify with the head chef before confirming anything to the guest.","Recipes can contain allergens that the menu doesn't show.",true,"Service Training Program v2026/01, service do's and don'ts","Wording chosen because the menus don't mark every nut item (see MENU_ALLERGEN_FLAGS.md).","review","David","2026-10-16",null,1],["sop-allergen-protocol-0004","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"mcq","If a replacement dish is needed for a guest with an allergy, what must the kitchen use?",null,["Designated equipment","The same pan, wiped clean","Whatever is free","Disposable cutlery only"],["Designated equipment"],"Use designated equipment when a guest has declared an allergy.","Traces from shared equipment can be enough to cause a reaction.",true,"Service Training Program v2026/01, allergen protocol",null,"review","David","2026-10-16",null,1],["sop-allergen-protocol-0005","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"multi","Which of these are among the 14 major allergens? Pick all that apply.",null,["Celery","Mustard","Sesame","Lupin","Garlic","Tomato"],["Celery","Mustard","Sesame","Lupin"],"The 14 are: cereals with gluten, crustaceans, eggs, fish, lupin, milk, molluscs, mustard, tree nuts, peanuts, sesame, soybeans, sulphites and celery.","Knowing all 14 helps you spot when to involve the kitchen.",true,"Service Training Program v2026/01, allergen awareness, life-critical protocol",null,"review","David","2026-10-16",null,1],["sop-allergen-protocol-0006","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"multi","Which of these are among the 14 major allergens? Pick all that apply.",null,["Molluscs","Crustaceans","Sulphites","Peanuts","Chicken","Rice"],["Molluscs","Crustaceans","Sulphites","Peanuts"],"Molluscs, crustaceans, sulphites and peanuts are all on the list of 14. Chicken and rice are not.","Some allergens, like sulphites in wine, are easy to forget.",true,"Service Training Program v2026/01, allergen awareness, life-critical protocol",null,"review","David","2026-10-16",null,1],["sop-allergen-protocol-0007","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"order","A guest raises an allergen concern about their food. Put the steps in order.",null,["Escalate","Document","Verify","Isolate"],["Verify","Isolate","Escalate","Document"],"Verify the ingredients with the head chef, isolate with designated equipment for any replacement, escalate to a manager, and document the incident.","Allergen complaints are medical, not a service issue.",true,"Service Training Program v2026/01, allergen and safety complaints",null,"review","David","2026-10-16",null,1],["sop-allergen-protocol-0008","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"scenario","A guest thinks a dish contained their allergen but says they feel fine. What now?",null,["Involve a manager now and log it","Apologise and move on","Offer dessert on the house","Wait to see if they feel unwell"],["Involve a manager now and log it"],"Involve a manager immediately, however minor the guest makes it sound, and log the incident even if no reaction occurred.","Reactions can start later, and the log helps stop it happening again.",true,"Service Training Program v2026/01, allergen and safety complaints",null,"review","David","2026-10-16",null,1],["sop-allergen-protocol-0009","sop","allergen-protocol",1,["host","server","runner","bar","barista"],"mcq","Who confirms the ingredients of a dish for a guest with an allergy?",null,["The head chef","The waiter, from the menu","The host","The guest's friends"],["The head chef"],"Always verify allergens with the head chef. Never guess.","The head chef knows every recipe and any change made today.",true,"Service Training Program v2026/01, service do's and don'ts; Operations Manual v2026/01, allergen protocol",null,"review","David","2026-10-16",null,1],["sop-guest-recovery-0010","sop","guest-recovery",1,["host","server","runner","bar","barista"],"order","Put the LEARN steps for handling a complaint in order.",null,["Resolve","Listen","Notify","Apologise","Empathise"],["Listen","Empathise","Apologise","Resolve","Notify"],"LEARN: Listen, Empathise, Apologise, Resolve, Notify.","The same calm steps every time turn a complaint into loyalty.",false,"Service Training Program v2026/01, the LEARN recovery method",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0011","sop","guest-recovery",1,["host","server","runner","bar","barista"],"mcq","In LEARN, what does the N (Notify) step mean?",null,["Follow up, and log the issue","Notify the guest's company","Tell the next shift only","Send the guest a voucher"],["Follow up, and log the issue"],"Notify: follow up to confirm the guest is satisfied, and log the issue so it doesn't happen again.","Logging it is how the team fixes the cause, not just the table.",false,"Service Training Program v2026/01, the LEARN recovery method",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0012","sop","guest-recovery",1,["host","server","runner","bar","barista"],"mcq","A guest is complaining. While they speak, what do you do?",null,["Listen without interrupting","Explain what happened","Defend the kitchen","Start offering solutions"],["Listen without interrupting"],"Listen first: give full attention and don't interrupt, explain or defend. Let the guest finish.","Guests want to be heard before anything else.",false,"Service Training Program v2026/01, the LEARN recovery method",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0013","sop","guest-recovery",1,["host","server","runner","bar","barista"],"mcq","Which phrase should you avoid with an unhappy guest?",null,["\"That's not my section.\"","\"Thank you for telling me, let me make this right.\"","\"I'll check with the kitchen myself.\"","\"Let me get this sorted for you immediately.\""],["\"That's not my section.\""],"Avoid phrases like \"That's not my section\" or \"There's nothing I can do\". An unhappy guest is your responsibility, whichever section they're in.","Guests want someone to own the problem.",false,"Service Training Program v2026/01, script: what to say",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0014","sop","guest-recovery",1,["host","server","runner","bar","barista"],"scenario","\"This was supposed to be hot, it's barely warm.\" What's the right first action?",null,["Apologise, replace it now, take it off the bill and tell the kitchen","Offer a dessert instead","Reheat the same plate","Explain the kitchen is busy"],["Apologise, replace it now, take it off the bill and tell the kitchen"],"For a cold or incorrect dish: apologise, remove it from the bill, replace it immediately and notify the kitchen.","Acting fast shows the guest we care more about them than the bill.",false,"Service Training Program v2026/01, complaint scenario playbook",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0015","sop","guest-recovery",1,["host","server","runner","bar","barista"],"scenario","\"We've waited 40 minutes and nothing's come out.\" What do you do?",null,["Acknowledge it, update them honestly and offer a complimentary item","Say it will be out soon","Blame the kitchen","Offer to cancel the order"],["Acknowledge it, update them honestly and offer a complimentary item"],"For a long wait: acknowledge, update the guest, offer a complimentary item. Escalate if the wait is over twice the normal time.","Honest updates calm guests far more than vague promises.",false,"Service Training Program v2026/01, complaint scenario playbook",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0016","sop","guest-recovery",1,["host","server","runner","bar","barista"],"multi","Which of these can you resolve yourself, without a manager? Pick all that apply.",null,["Replacing a dish or drink","Removing a single item from the bill","Adjusting seating, noise or pace","A guest asking for a refund","A guest saying the food made them ill"],["Replacing a dish or drink","Removing a single item from the bill","Adjusting seating, noise or pace"],"You can replace a dish or drink, remove a single item, apologise and follow up, and adjust seating, noise or pace. Refunds and illness or injury go to a manager.","Fixing small things on the spot keeps the guest's visit on track.",false,"Service Training Program v2026/01, resolve it or escalate it?",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0017","sop","guest-recovery",1,["host","server","runner","bar","barista"],"mcq","When you bring in a manager for a complaint, how do you hand over?",null,["Introduce the manager personally, with the full story","Tell the guest a manager is coming and leave","Send the manager to the table alone","Wait for the guest to ask twice"],["Introduce the manager personally, with the full story"],"Flag it early, hand over warmly by introducing the manager personally, and give them full context. Never disappear without a word.","The guest shouldn't have to repeat the problem.",false,"Service Training Program v2026/01, the escalation protocol",null,"live","David","2026-10-16",null,1],["sop-guest-recovery-0018","sop","guest-recovery",1,["host","server","runner","bar","barista"],"mcq","A guest is getting louder. What helps calm things down?",null,["Lower your voice slightly and slow your pace","Match their volume so they hear you","Stand close beside them","Fill every pause with an explanation"],["Lower your voice slightly and slow your pace"],"Lower your voice and slow down: calm is contagious. Keep an open posture and give the guest space.","A calm voice is the quickest way to bring the temperature down.",false,"Service Training Program v2026/01, read the room",null,"live","David","2026-10-16",null,1],["sop-house-standards-0019","sop","house-standards",1,["host","server","runner","bar","barista"],"multi","What are the four Maison Mathis brand pillars? Pick all that apply.",null,["Quality","Simplicity","Authenticity","Warmth","Speed","Luxury"],["Quality","Simplicity","Authenticity","Warmth"],"Quality, Simplicity, Authenticity and Warmth.","The pillars explain why we do things the way we do.",false,"Operations Manual v2026/01, brand pillars; Service Training Program v2026/01, day 1",null,"live","David","2026-10-16",null,1],["sop-house-standards-0020","sop","house-standards",1,["host","server","runner","bar","barista"],"mcq","What does the \"Swan Theory\" ask of you during a busy service?",null,["Look calm and graceful while working fast","Move slowly so guests relax","Tell guests how busy it is","Stay at the bar until it's quieter"],["Look calm and graceful while working fast"],"Appear calm and graceful always, working at full speed beneath the surface. Guests should never feel the pressure.","Guests relax when the team looks in control.",false,"Service Training Program v2026/01, our service philosophy",null,"live","David","2026-10-16",null,1],["sop-house-standards-0021","sop","house-standards",1,["host","server","runner","bar","barista"],"scenario","You pass an empty glass on a table in another waiter's section. What do you do?",null,["Offer a refill or clear it yourself","Tell that waiter later","Leave it, it's not your section","Wait for the runner"],["Offer a refill or clear it yourself"],"The Gentleman's Agreement: an empty glass, an uncleared table or a guest needing help is your responsibility, whatever your section.","Guests see one team, not sections.",false,"Service Training Program v2026/01, our service philosophy",null,"live","David","2026-10-16",null,1],["sop-house-standards-0022","sop","house-standards",1,["host","server","runner","bar","barista"],"mcq","A guest asks something you don't know. What do you say?",null,["\"Let me find out for you\"","\"I don't know\"","\"That's not on the menu\"","\"Ask your waiter\""],["\"Let me find out for you\""],"Never say \"I don't know\" without immediately offering to find out. Then always follow up.","Guests trust a team that finds the answer.",false,"Service Training Program v2026/01, guest service standards",null,"live","David","2026-10-16",null,1],["sop-house-standards-0023","sop","house-standards",1,["host","server","runner","bar","barista"],"mcq","When can you use your personal phone on the floor?",null,["Never on the floor","When it's quiet","To check the time","If a guest can't see you"],["Never on the floor"],"No personal phone use on the floor.","Guests should always see a team that's focused on them.",false,"Service Training Program v2026/01, guest service standards; Operations Manual v2026/01, guest service standards",null,"live","David","2026-10-16",null,1],["sop-house-standards-0024","sop","house-standards",1,["host","server","runner","bar","barista"],"multi","What does the pre-shift briefing cover? Pick all that apply.",null,["Daily specials","Reservations","Items that are unavailable (86'd)","Known VIPs","Staff wages"],["Daily specials","Reservations","Items that are unavailable (86'd)","Known VIPs"],"Every shift starts with a 15-minute briefing: specials, reservations, 86'd items, known VIPs, and one team focus.","Knowing these before the doors open stops surprises at the table.",false,"Operations Manual v2026/01, shift management",null,"live","David","2026-10-16",null,1],["sop-house-standards-0025","sop","house-standards",1,["host","server","runner","bar","barista"],"mcq","How long is the pre-shift briefing?",null,["15 minutes","5 minutes","30 minutes","1 hour"],["15 minutes"],"Every shift begins with a 15-minute team briefing.","It's the team's one chance to plan the shift together.",false,"Operations Manual v2026/01, shift management; Service Training Program v2026/01, shift management",null,"live","David","2026-10-16",null,1],["sop-opening-closing-0026","sop","opening-closing",1,["host","server","runner","bar","barista"],"multi","FOH opening checklist: which of these are on it? Pick all that apply.",null,["Tables polished, glassware spotless","Salt, pepper and condiments restocked","Menus clean and in position","Music set low to moderate","Chairs stacked on tables"],["Tables polished, glassware spotless","Salt, pepper and condiments restocked","Menus clean and in position","Music set low to moderate"],"Polish tables and glassware, restock condiments, set clean menus, and set music low to moderate for opening.","The first guest of the day deserves the same house as the hundredth.",false,"Operations Manual v2026/01, opening procedures",null,"live","David","2026-10-16",null,1],["sop-opening-closing-0027","sop","opening-closing",1,["barista","host","server"],"mcq","When should baked goods be on display?",null,["30 minutes before opening","At opening time","Once the first guest orders","By lunchtime"],["30 minutes before opening"],"Baked goods are displayed 30 minutes before opening.","The bakery display is a marketing tool from the first minute.",false,"Operations Manual v2026/01, opening procedures",null,"live","David","2026-10-16",null,1],["sop-opening-closing-0028","sop","opening-closing",1,["barista","host","server"],"mcq","How often is the bakery display refreshed through the day?",null,["Every 90 minutes","Once at lunch","Every 4 hours","Only when empty"],["Every 90 minutes"],"Refresh the bakery display every 90 minutes: clean trays, labels visible, nothing crumbled or stale.","A fresh display sells; a tired one doesn't.",false,"Operations Manual v2026/01, bakery operations",null,"live","David","2026-10-16",null,1],["sop-opening-closing-0029","sop","opening-closing",1,["host","server","runner","bar","barista"],"scenario","It's near closing and one table is still chatting over coffee. What do you do?",null,["Let them finish without rushing them","Start stacking chairs nearby","Bring the bill unasked","Turn the lights down"],["Let them finish without rushing them"],"At wind-down, give final tables a genuine farewell; remaining guests are not rushed.","The last guest's memory of us matters as much as the first's.",false,"Operations Manual v2026/01, closing procedures",null,"live","David","2026-10-16",null,1],["sop-controls-0030","sop","controls",1,["host","server","runner","bar","barista"],"scenario","A guest complains and you want to give a discount. What's the rule?",null,["Get manager authorisation, with a logged reason","Give it if the guest is upset","Give up to 10% yourself","Ask the guest how much they want"],["Get manager authorisation, with a logged reason"],"All voids and discounts need manager authorisation and a logged reason, even to solve a complaint.","It protects you, the guest and the business.",false,"Service Training Program v2026/01, void and discount controls; Operations Manual v2026/01, void and discount controls",null,"live","David","2026-10-16",null,1],["sop-controls-0031","sop","controls",1,["server","bar"],"mcq","When should an order be entered into the POS?",null,["Immediately, as you take it","At the end of the table's visit","When the kitchen asks","Before closing"],["Immediately, as you take it"],"Every order goes into the POS immediately, so errors are caught at order stage, not at billing.","The kitchen starts cooking sooner and the bill is right.",false,"Service Training Program v2026/01, POS accuracy",null,"live","David","2026-10-16",null,1],["sop-safety-basics-0032","sop","safety-basics",1,["host","server","runner","bar","barista"],"multi","When is handwashing mandatory? Pick all that apply.",null,["Before handling food","After handling waste","After any break","Only at the start of a shift"],["Before handling food","After handling waste","After any break"],"Wash hands before handling food, after handling waste and after any break.","Clean hands are the simplest way to protect guests.",false,"Operations Manual v2026/01, personal hygiene; Service Training Program v2026/01, personal hygiene",null,"live","David","2026-10-16",null,1],["sop-safety-basics-0033","sop","safety-basics",1,["host","server","runner","bar","barista"],"mcq","A drink spills on the floor. What comes first?",null,["Put out a wet floor sign straight away","Finish serving your table","Tell the cleaner at closing","Cover it with napkins"],["Put out a wet floor sign straight away"],"Deploy a wet floor sign immediately after any spill, then clean it up.","A slip can injure a guest or a teammate in seconds.",false,"Operations Manual v2026/01, slip and trip prevention",null,"live","David","2026-10-16",null,1],["sop-safety-basics-0034","sop","safety-basics",1,["host","server","runner","bar","barista"],"mcq","A teammate trips but isn't hurt. Does it need logging?",null,["Yes, every incident and near miss is logged that day","Only if someone is hurt","Only if a guest saw it","No, near misses don't count"],["Yes, every incident and near miss is logged that day"],"Every incident, however minor, is logged on the day it happens, and near misses are reported and reviewed.","Near misses show where the next accident could happen.",false,"Operations Manual v2026/01, incident reporting; Service Training Program v2026/01, first aid and incident reporting",null,"live","David","2026-10-16",null,1],["sop-safety-basics-0035","sop","safety-basics",1,["host","server","runner","bar","barista"],"mcq","You feel unwell with a stomach bug before your shift. What's right?",null,["Don't handle food","Handle food but wash your hands more","Handle food wearing gloves","Handle only cold food"],["Don't handle food"],"Team members with any illness affecting food safety must not handle food.","It protects guests and teammates from getting ill.",false,"Operations Manual v2026/01, personal hygiene",null,"live","David","2026-10-16",null,1],["food-menu-basics-0001","food","menu-basics",1,["server","host","runner","bar","barista"],"mcq","On our menus, what does (R) next to a dish mean?",null,["Raw","Recommended","Regional","Reduced fat"],["Raw"],"(R) marks a raw dish, such as the Wagyu Beef Carpaccio, Wagyu Tartare or Seabream Ceviche.","Some guests, such as pregnant guests, may want to know a dish is raw before ordering.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, legend",null,"live","David","2026-10-16",null,1],["food-menu-basics-0002","food","menu-basics",1,["server","host","runner","bar","barista"],"mcq","On our menus, what does (A) next to a dish mean?",null,["It contains alcohol","It's an autumn special","It's available all day","It's served with aioli"],["It contains alcohol"],"(A) marks alcohol, for example the Classic Belgian Beef Stew, braised in Leffe Brune, and the beer-battered Fish and Chips.","Some guests don't take alcohol in any form, including in cooking.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, legend; AR breakfast menu, 20260914_MM-AR-BREAKFAST53, legend",null,"live","David","2026-10-16",null,1],["food-menu-basics-0003","food","menu-basics",1,["server","host","runner","bar","barista"],"mcq","What's the difference between (V) and (VG) on our menus?",null,["(V) is vegetarian, (VG) is vegan","(V) is vegan, (VG) is vegetarian","(VG) means very good","They mean the same"],["(V) is vegetarian, (VG) is vegan"],"(V) marks vegetarian dishes; (VG) marks vegan ones, such as the Sourdough Avocado and the Superfood Salad.","A vegan guest needs the right one; a vegetarian dish may still contain dairy or egg.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, legend; AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, legend",null,"live","David","2026-10-16",null,1],["food-menu-basics-0004","food","menu-basics",1,["server","host","runner","bar","barista"],"mcq","Which breakfast dish is marked vegan (VG)?",null,["Sourdough Avocado","Toast Champignon","Perfect Scrambled","Benedict Forestiere"],["Sourdough Avocado"],"Sourdough Avocado and the Vegan Breakfast are marked (VG). Toast Champignon, Perfect Scrambled and Benedict Forestiere are vegetarian (V).","Vegan guests need to know their options straight away.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53",null,"live","David","2026-10-16",null,1],["food-menu-basics-0005","food","menu-basics",1,["server","host","runner","bar","barista"],"scenario","A guest who doesn't eat pork wants the M/M Breakfast. What can you offer?",null,["The Halal choice","Nothing, it contains pork","The same plate without the ham","A Full English instead"],["The Halal choice"],"The M/M Breakfast and The Full English both come as Pork (P) or Halal choice.","Knowing the choice means the guest still gets the breakfast they wanted.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53",null,"live","David","2026-10-16",null,1],["food-menu-basics-0006","food","menu-basics",1,["server","host","runner","bar"],"mcq","Until what time are sandwiches and toasts served?",null,["5 pm","2 pm","12 pm","All day"],["5 pm"],"Sandwiches and toasts are served till 5 pm.","You can suggest them confidently before 5, and steer later guests elsewhere.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sandwiches and Toasts",null,"live","David","2026-10-16",null,1],["food-menu-basics-0007","food","menu-basics",1,["server","host","runner","bar"],"mcq","From what time are the stone-baked pizzas available?",null,["12 pm","8 am","5 pm","6 pm"],["12 pm"],"M/M Stone Baked Pizzas are available daily from 12 pm onwards.","Breakfast guests asking for pizza need the right answer.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Stone Baked Pizzas",null,"live","David","2026-10-16",null,1],["food-menu-basics-0008","food","menu-basics",1,["server","host","runner","bar","barista"],"mcq","When is the breakfast menu served at Arabian Ranches?",null,["Daily, 8 am to 2 pm","Weekends only","Until 11 am","All day"],["Daily, 8 am to 2 pm"],"The breakfast menu is served daily between 8 am and 2 pm.","Late-morning guests often ask if they can still order breakfast.",false,"David, 16 Oct 2026 (menu service times)",null,"live","David","2026-10-16",null,1],["food-menu-basics-0009","food","menu-basics",1,["server","host","runner","bar"],"mcq","Pizzas for a table come out at different times. Why?",null,["They're served as ready, for quality","The kitchen forgot them","One pizza oven only","Guests asked for it"],["They're served as ready, for quality"],"Pizzas are served as they're ready, to make sure every dish is at its best.","Telling guests at the order avoids surprise later.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Stone Baked Pizzas",null,"live","David","2026-10-16",null,1],["food-menu-basics-0010","food","menu-basics",1,["server","host","runner","bar"],"mcq","What is the base of our stone-baked pizzas?",null,["Sourdough","Thin and crispy wheat","Gluten-free dough","Focaccia"],["Sourdough"],"Our pizzas are stone-baked with a sourdough base.","It's part of what makes our pizza different; say it with pride.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Stone Baked Pizzas",null,"live","David","2026-10-16",null,1],["food-menu-basics-0011","food","menu-basics",1,["server","host","runner","bar","barista"],"mcq","A guest wants a benedict but avoids gluten. What can you offer?",null,["A change to gluten-free portobello mushroom, free","Nothing, benedicts contain bread","A change to sourdough","Extra hollandaise"],["A change to gluten-free portobello mushroom, free"],"Benedicts can change to gluten-free portobello mushroom, free of charge.","Offering the swap keeps the guest's choice open.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Benedicts","For a coeliac guest the head chef still confirms the dish.","live","David","2026-10-16",null,1],["food-menu-basics-0012","food","menu-basics",1,["server","host","runner","bar"],"mcq","A guest avoiding gluten wants a pasta dish. What can you offer?",null,["Gluten-free pasta, free of charge","Gluten-free pasta for AED 10","Rice instead","Nothing"],["Gluten-free pasta, free of charge"],"Any pasta can change to gluten-free pasta, free of charge.","Guests love an easy yes.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Pasta","For a coeliac guest the head chef still confirms the dish.","live","David","2026-10-16",null,1],["food-menu-basics-0013","food","menu-basics",1,["server","host","runner","bar"],"mcq","Is a discount applied to mussels?",null,["No, no discounts apply to mussels","Yes, like everything else","Only at lunch","Only for 1 kg"],["No, no discounts apply to mussels"],"The menu says no discounts are applicable on mussels.","Knowing this avoids an awkward moment at the bill.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Mussels and Fries",null,"live","David","2026-10-16",null,1],["food-breakfast-0014","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","Which benedict comes with béarnaise instead of hollandaise?",null,["Belgian Benedict","Classic Benedict","Benedict Royal","Benedict Forestiere"],["Belgian Benedict"],"The Belgian Benedict has pork bacon, sourdough, caramelized onion and béarnaise. The others come with hollandaise.","Guests who love béarnaise will thank you for pointing it out.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Benedicts",null,"live","David","2026-10-16",null,1],["food-breakfast-0015","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","What's on the Benedict Royal?",null,["Smoked salmon and spinach","Prosciutto ham and pesto","Pulled beef and chili beans","Mushrooms and truffle oil"],["Smoked salmon and spinach"],"Benedict Royal: smoked salmon and spinach, brioche, hollandaise.","Guests often ask for \"the salmon one\".",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Benedicts",null,"live","David","2026-10-16",null,1],["food-breakfast-0016","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","Which benedict has a spicy hollandaise?",null,["Pulled Beef Benedict","Classic Benedict","Benedict San Daniele","Benedict Royal"],["Pulled Beef Benedict"],"The Pulled Beef Benedict has 6-hour slow-cooked BBQ pulled beef, brioche, M/M chili beans and spicy hollandaise.","Mention the spice so nobody gets a surprise.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Benedicts",null,"live","David","2026-10-16",null,1],["food-breakfast-0017","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","Which benedict is vegetarian (V)?",null,["Benedict Forestiere","Benedict San Daniele","Belgian Benedict","Benedict Royal"],["Benedict Forestiere"],"Benedict Forestiere: mushrooms, truffle oil, spinach, herbs, brioche and hollandaise, marked (V).","It's the benedict to suggest to vegetarian guests.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Benedicts",null,"live","David","2026-10-16",null,1],["food-breakfast-0018","food","breakfast",1,["server","host","runner","bar","barista"],"multi","What comes on The Full English? Pick all that apply.",null,["Black pudding","Heinz baked beans","Hash brown","Grilled tomato","Avocado","Smoked salmon"],["Black pudding","Heinz baked beans","Hash brown","Grilled tomato"],"Sunny-side-up eggs, sourdough toast, bacon, sausage, grilled tomato, sautéed mushrooms, Heinz baked beans, black pudding and hash brown.","Guests ask what's on it before they commit to a big breakfast.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Traditional Breakfast",null,"live","David","2026-10-16",null,1],["food-breakfast-0019","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","What makes the Double Full English \"double\"?",null,["Extra bacon, sausage, black pudding and hashbrown","Two plates for sharing","Double eggs only","A larger toast"],["Extra bacon, sausage, black pudding and hashbrown"],"The Double Full English adds extra bacon, sausage, black pudding and hashbrown.","Helps hungry guests choose.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Traditional Breakfast",null,"live","David","2026-10-16",null,1],["food-breakfast-0020","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","How many eggs are in the Perfect Scrambled?",null,["3","2","4","1"],["3"],"Perfect Scrambled is 3 free range eggs on sourdough toast. Smoked salmon can be added.","Portion questions are common; a confident answer builds trust.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Omelets and Eggs",null,"live","David","2026-10-16",null,1],["food-breakfast-0021","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","Which eggs can a guest choose for \"Simply Your Way\"?",null,["Fried, sunny side up, boiled, poached or over easy","Scrambled only","Poached only","Omelet or scrambled"],["Fried, sunny side up, boiled, poached or over easy"],"Simply Your Way is 2 free range eggs, fried, sunny side up, boiled, poached or over easy, with sourdough toast.","Asking how they'd like their eggs is part of taking the order.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Omelets and Eggs",null,"live","David","2026-10-16",null,1],["food-breakfast-0022","food","breakfast",1,["server","host","runner","bar","barista"],"multi","What's in the Shakshuka? Pick all that apply.",null,["Cherry tomato","2 free range eggs","Chili","Coriander","Feta","Avocado"],["Cherry tomato","2 free range eggs","Chili","Coriander"],"Shakshuka: cherry tomato, 2 free range eggs, chili, a blend of spices, coriander and caramelized onion. Beef or pork chorizo can be added.","Guests often ask how spicy it is; chili is listed.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Omelets and Eggs",null,"live","David","2026-10-16",null,1],["food-breakfast-0023","food","breakfast",1,["server","host","runner","bar","barista"],"multi","What's in the Yoghurt and Eggs? Pick all that apply.",null,["Dukkah","Chili butter","Feta","Fresh mint","Hollandaise","Bacon"],["Dukkah","Chili butter","Feta","Fresh mint"],"Poached eggs, dukkah, chili butter, fresh mint, feta, chili crisp and roasted zucchini and capsicum. Sujuk sausage can be added.","It's an unusual dish, so guests often ask what it is.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Omelets and Eggs",null,"live","David","2026-10-16",null,1],["food-breakfast-0024","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","What can guests choose with the Signature Granola?",null,["Greek yoghurt or soy yoghurt","Milk or cream","Honey or jam","Hot or cold"],["Greek yoghurt or soy yoghurt"],"The Signature Granola comes with Greek yoghurt or soy yoghurt and seasonal fruits.","It gives guests a choice of yoghurt.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Healthy Section",null,"live","David","2026-10-16",null,1],["food-breakfast-0025","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","How many pancakes come in the Blueberry Pancakes?",null,["3","2","4","5"],["3"],"All our pancake dishes come with 3 pancakes. Blueberry has blueberry jam, fresh blueberries, cream and icing sugar.","Helps guests decide whether to share.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Pancakes and Sweets",null,"live","David","2026-10-16",null,1],["food-breakfast-0026","food","breakfast",1,["server","host","runner","bar","barista"],"mcq","What is the Vanilla French Toast served with?",null,["Vanilla mascarpone crème, rhubarb compote, pistachio","Chocolate ganache and almonds","Maple syrup and bacon","Fresh strawberries and cream"],["Vanilla mascarpone crème, rhubarb compote, pistachio"],"Vanilla French Toast: vanilla mascarpone crème, rhubarb compote and pistachio.","Describing it well helps it sell.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Pancakes and Sweets",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0027","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","Where do our Huitres Hervé #3 oysters come from?",null,["Normandy, France","Brittany, France","Ireland","Zeeland, Netherlands"],["Normandy, France"],"Huitres Hervé #3 oysters are from Normandy, France, sold by the piece.","Guests ordering oysters often ask where they're from.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sharing",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0028","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What cheese is in our \"Van Tricht\" cheese croquettes?",null,["An aged gouda, \"Farmdal OG Krystal\"","Comté","Grana Padano","Camembert"],["An aged gouda, \"Farmdal OG Krystal\""],"Our signature croquettes use a specially selected aged gouda, \"Farmdal OG Krystal\", served with fried parsley and a whole grain mustard dip.","It's a signature recipe, worth telling guests about.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sharing",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0029","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","How many snails come in the Escargots de Bourgogne?",null,["12","6","8","10"],["12"],"12 Burgundy snails in garlic and parsley butter, with sourdough.","A classic guests often ask about.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Soups and Starters",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0030","food","lunch-dinner",1,["server","host","runner","bar"],"multi","What's in the Vitello Tonnato? Pick all that apply.",null,["Slow-roasted veal tenderloin","Tuna","Anchovy","Capers","Pork belly","Pistachio"],["Slow-roasted veal tenderloin","Tuna","Anchovy","Capers"],"Vitello Tonnato: slow-roasted veal tenderloin, tuna, anchovy, capers and Grana Padano.","Guests are often surprised it has fish; tell them.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Soups and Starters",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0031","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What makes the Seabream Ceviche's \"leche de tigre\"?",null,["Ají amarillo","Coconut milk","Soy sauce","Basil emulsion"],["Ají amarillo"],"Seabream Ceviche (R): ají amarillo \"leche de tigre\", fresh corn salsa, avocado, sweet potato and nachos.","Guests ask what leche de tigre is.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Soups and Starters",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0032","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","Which starter is served raw?",null,["Wagyu Tartare","Escargots de Bourgogne","Garlic Shrimps","Soup of the Day"],["Wagyu Tartare"],"Wagyu Tartare is marked (R): raw Wagyu beef with a classic Belgian dressing, toasted sourdough and crispy potato.","Guests should know a dish is raw before ordering.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Soups and Starters",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0033","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What's in the Classic Caesar that makes it (P)?",null,["Pork bacon","Pork croutons","Ham dressing","Salami"],["Pork bacon"],"Classic Caesar: lettuce, Caesar dressing, Grana Padano PDO, croutons and pork bacon.","Guests who avoid pork need to know before ordering.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Salads",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0034","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What comes with every M/M burger?",null,["Belgian fries","Skinny fries","Garden salad","Sweet potato fries"],["Belgian fries"],"All M/M burgers are served with Belgian fries.","Saves the guest asking, and opens a chance to suggest an upgrade.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Burgers",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0035","food","lunch-dinner",1,["server","host","runner","bar"],"multi","What's on the Signature Burger? Pick all that apply.",null,["Angus beef patty","Peppercorn sauce","Onion jam","Camembert cheese","Cheddar","BBQ sauce"],["Angus beef patty","Peppercorn sauce","Onion jam","Camembert cheese"],"Signature Burger: Angus beef patty, peppercorn sauce, onion jam, camembert, roquette lettuce, mushrooms, M/M bun.","Knowing the differences between burgers helps guests choose.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Burgers",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0036","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What is the Classic Belgian Beef Stew braised in?",null,["Leffe Brune","Red wine","Guinness","Beef stock only"],["Leffe Brune"],"Classic Belgian Beef Stew and Fries (A): beef braised in Leffe Brune, with Belgian fries and endive salad.","It's a true Belgian classic, and Leffe Brune is on draught to pair with it.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Meat Specials",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0037","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","How much does the Grilled Rib Eye weigh?",null,["300 gr","200 gr","220 gr","250 gr"],["300 gr"],"Grilled Rib Eye is 300 gr, Prime Angus, grain fed. The Steak and Fries is 200 gr, the tenderloin 220 gr and the Wagyu striploin 250 gr.","Guests choose steaks by size; know them.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, From the Farm",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0038","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","Which steak is Australian \"Westholme\" Wagyu, MB 4-5?",null,["Grilled Wagyu Striploin 250 gr","Grilled Rib Eye 300 gr","Steak and Fries 200 gr","Black Angus Grilled Tenderloin 220 gr"],["Grilled Wagyu Striploin 250 gr"],"The Grilled Wagyu Striploin is Australian \"Westholme\" Wagyu MB 4-5, with red wine shallots and Padron pepper.","Guests paying for Wagyu like to hear where it's from.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, From the Farm",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0039","food","lunch-dinner",1,["server","host","runner","bar"],"multi","Which sauces can guests add to a steak? Pick all that apply.",null,["Béarnaise","Green peppercorn","Forestal mushroom","Blue cheese","Hollandaise","Chimichurri"],["Béarnaise","Green peppercorn","Forestal mushroom","Blue cheese"],"Four sauces: Forestal mushroom, green peppercorn, béarnaise and blue cheese, AED 5 each.","Offering a sauce by name is an easy, welcome suggestion.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sauces",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0040","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What sizes do our mussels come in?",null,["½ kg or 1 kg","500 g only","Small, medium or large","By the piece"],["½ kg or 1 kg"],"Mussels come as ½ kg or 1 kg, served with Belgian fries and a dip.","Helps guests decide whether to share.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Mussels and Fries",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0041","food","lunch-dinner",1,["server","host","runner","bar"],"multi","Which mussel styles are on the menu? Pick all that apply.",null,["Classic","Garlic and Cream","Roquefort","Thai Curry","Mediterranean","Tomato and Chorizo"],["Classic","Garlic and Cream","Roquefort","Thai Curry","Mediterranean"],"Five styles: Classic, Garlic and Cream, Mediterranean, Roquefort and Thai Curry.","Mussels and fries is our tradition; know every style.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Mussels and Fries",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0042","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","How are the Classic mussels prepared?",null,["Fisherman's style: mirepoix, white wine, parsley","Cream, garlic and white wine","Thai curry and coconut milk","Roquefort cheese and cream"],["Fisherman's style: mirepoix, white wine, parsley"],"Classic mussels are fisherman's style, with mirepoix, white wine and parsley.","It's the one to suggest to first-timers.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Mussels and Fries",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0043","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What's in the Fish and Chips?",null,["Beer-battered cod, mushy peas, tartare, fries","Breaded hake, salad, fries","Grilled cod, mash, peas","Battered sea bass, chips, aioli"],["Beer-battered cod, mushy peas, tartare, fries"],"Fish and Chips (A): beer-battered flaky cod, mushy peas, tartare and fries.","The (A) is because of the beer batter.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, From the Sea",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0044","food","lunch-dinner",1,["server","host","runner","bar"],"multi","Which cheeses are on the Quatro Formaggi pizza? Pick all that apply.",null,["Mozzarella","Taleggio","Gorgonzola","Provolone","Feta","Cheddar"],["Mozzarella","Taleggio","Gorgonzola","Provolone"],"Quatro Formaggi: mozzarella, Taleggio, Gorgonzola and Provolone.","Cheese lovers ask which four.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Stone Baked Pizzas",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0045","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What meat is on the Pepperoni pizza?",null,["Beef salami","Pork salami","Turkey ham","Beef chorizo"],["Beef salami"],"The Pepperoni pizza has mozzarella, olives and beef salami.","Guests who avoid pork often ask.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Stone Baked Pizzas",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0046","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What's in a Dame Blanche?",null,["Vanilla ice cream, Belgian chocolate sauce, chocolate crumble, whipped cream","Speculoos ice cream and caramel","Strawberry ice cream and meringue","Brownie and chocolate ice cream"],["Vanilla ice cream, Belgian chocolate sauce, chocolate crumble, whipped cream"],"Dame Blanche: 3 scoops of vanilla ice cream, Belgian chocolate sauce, chocolate crumble and whipped cream.","A Belgian classic to recommend with pride.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sundaes",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0047","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","What fruit is in our Tarte Tatin?",null,["Royal Gala apple","Pear","Peach","Pineapple"],["Royal Gala apple"],"Tarte Tatin: Royal Gala apple, puff pastry and vanilla ice cream. Good for sharing.","Describing it helps it sell.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Desserts",null,"live","David","2026-10-16",null,1],["food-lunch-dinner-0048","food","lunch-dinner",1,["server","host","runner","bar"],"mcq","Which dish on the autumn menu is a Hungarian beef stew?",null,["Goulash","Confit Duck Leg","Lamb Chops","Wild Mushroom Ravioli"],["Goulash"],"Goulash: Hungarian beef stew with red peppers, paprika, tomato, potato, toasted sourdough and sour cream.","Seasonal dishes change; know the current ones.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Autumn Menu",null,"live","David","2026-10-16",null,1],["food-allergens-breakfast-0049","food","allergens-breakfast",1,["server","host","runner","bar","barista"],"mcq","Which nut is listed on the Vanilla French Toast?",null,["Pistachio","Hazelnut","Walnut","Pecan"],["Pistachio"],"Vanilla French Toast lists pistachio, a tree nut.","Guests with a nut allergy must know before ordering.",true,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live. The menu doesn't mark this dish (N).","review","David","2026-10-16",null,1],["food-allergens-breakfast-0050","food","allergens-breakfast",1,["server","host","runner","bar","barista"],"mcq","Which nut is listed on the Chocolate French Toast?",null,["Toasted almonds","Pecan nuts","Hazelnuts","Pistachio"],["Toasted almonds"],"Chocolate French Toast lists toasted almonds, a tree nut.","Guests with a nut allergy must know before ordering.",true,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live. The menu doesn't mark this dish (N).","review","David","2026-10-16",null,1],["food-allergens-breakfast-0051","food","allergens-breakfast",1,["server","host","runner","bar","barista"],"mcq","Which nut is listed on the Banofee and Pecan Pancakes?",null,["Pecan nuts","Almonds","Walnuts","Cashews"],["Pecan nuts"],"Banofee and Pecan Pancakes list pecan nuts, a tree nut, and the dish is marked (N).","Guests with a nut allergy must know before ordering.",true,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-breakfast-0052","food","allergens-breakfast",1,["barista","server","bar"],"mcq","The Baobab Harmony smoothie lists which peanut ingredient?",null,["Peanut butter","Peanut oil","Crushed peanuts","Peanut milk"],["Peanut butter"],"Baobab Harmony lists peanut butter, and almond milk too: peanuts and tree nuts are both major allergens.","A peanut allergy can be severe; the guest must know.",true,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Smoothies","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live. The menu doesn't mark this drink (N).","review","David","2026-10-16",null,1],["food-allergens-breakfast-0053","food","allergens-breakfast",1,["barista","server","bar"],"mcq","What milk are the Matcha, Turmeric and Beetroot lattes served with?",null,["Almond milk","Oat milk","Soy milk","Cow's milk"],["Almond milk"],"The wellness lattes are served with almond milk. Almond is a tree nut.","Guests with a nut allergy may assume a latte is nut-free.",true,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Wellness Late","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live. The menu doesn't mark these drinks (N).","review","David","2026-10-16",null,1],["food-allergens-breakfast-0054","food","allergens-breakfast",1,["server","host","runner","bar","barista"],"mcq","Which allergen group does the crab in the Crab Omelet belong to?",null,["Crustaceans","Molluscs","Fish","Lupin"],["Crustaceans"],"Crab is a crustacean. The Crab Omelet is marked (S) for shellfish.","Shellfish allergies are common and can be severe.",true,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, Omelets and Eggs; Service Training Program v2026/01, 14 allergens","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0055","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which allergen group does calamari belong to?",null,["Molluscs","Crustaceans","Fish","Sesame"],["Molluscs"],"Calamari (squid) is a mollusc. It's in the Crispy Calamari and the Crispy-Skin Grilled Seabream.","A guest with a mollusc allergy may not think of squid.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39; Service Training Program v2026/01, 14 allergens","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live. The menu doesn't mark these dishes (S).","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0056","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which allergen group do the snails in the Escargots belong to?",null,["Molluscs","Crustaceans","Fish","None"],["Molluscs"],"Snails are molluscs, one of the 14 major allergens.","Guests rarely think of snails as shellfish.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39; Service Training Program v2026/01, 14 allergens","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live. The menu doesn't mark this dish (S).","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0057","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","The \"Espinaler\" Spanish olives are stuffed with what?",null,["Anchovy","Garlic","Pimento","Almond"],["Anchovy"],"They're 150 g of anchovy-stuffed \"Manzanilla Fina\" olives, so they contain fish.","A fish allergy guest could easily assume olives are safe.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sharing","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0058","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which pizza has anchovies?",null,["Napoletana","Margarita","Quatro Stagione","Diavola"],["Napoletana"],"The Napoletana has mozzarella, tomato sauce, anchovies and capers.","Fish allergies apply to pizza too.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, M/M Stone Baked Pizzas","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0059","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which nut is listed on the Tuna Tartare and Stracciatella?",null,["Pistachio","Pine nuts","Walnut","Almond"],["Pistachio"],"Tuna Tartare and Stracciatella (R, N) lists pistachio, with basil pesto.","Guests with a nut allergy must know before ordering.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Soups and Starters","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0060","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which nut is listed on the Chef's Salad?",null,["Pine nuts","Hazelnuts","Walnuts","Almonds"],["Pine nuts"],"Chef's Salad (P) (N) lists pine nuts.","Guests with a nut allergy must know before ordering.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Salads","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0061","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which nut is listed on the Roasted Beetroot and Feta?",null,["Hazelnuts","Pistachio","Pecans","Cashews"],["Hazelnuts"],"Roasted Beetroot and Feta (V) (N) (GF) lists hazelnuts.","Guests with a nut allergy must know before ordering.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Salads","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0062","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which nut is listed on the Butternut Pumpkin Salad?",null,["Toasted almonds","Walnuts","Pine nuts","Hazelnuts"],["Toasted almonds"],"Butternut Pumpkin Salad (V, N) lists toasted almonds.","Guests with a nut allergy must know before ordering.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Autumn Menu","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0063","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which nut comes with the M/M Cheese Selection?",null,["Walnuts","Almonds","Pecans","Pistachio"],["Walnuts"],"The M/M Cheese Selection (V) (N) comes with chutney, grapes, crackers and walnuts.","Guests with a nut allergy must know before ordering.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sharing","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0064","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","Which nut is listed on the Chocolate Crush sundae?",null,["Almond","Hazelnut","Pecan","Peanut"],["Almond"],"Chocolate Crush lists vanilla and chocolate ice cream, brownie, chocolate sauce, meringue and almond.","Guests with a nut allergy must know before ordering.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sundaes","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live. The menu doesn't mark this dish (N).","review","David","2026-10-16",null,1],["food-allergens-lunch-dinner-0065","food","allergens-lunch-dinner",1,["server","host","runner","bar"],"mcq","The béarnaise lists eggs and butter. Butter belongs to which allergen group?",null,["Milk","Eggs","Mustard","Soybeans"],["Milk"],"Butter is a milk product, so béarnaise contains milk as well as eggs.","Guests avoiding dairy often forget butter in sauces.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, Sauces; Service Training Program v2026/01, 14 allergens","[TO CONFIRM] Drafted from the menu's listed ingredients only, not the allergen matrix. Gerard to check before it goes live.","review","David","2026-10-16",null,1],["drk-bar-standards-0001","drinks","bar-standards",2,["bar"],"mcq","What is our standard spirit measure?",null,["30 ml","25 ml","35 ml","50 ml"],["30 ml"],"Every bartender uses a jigger for exact measurements; the standard measure is 30 ml.","Every guest gets the same drink, and over-pouring costs the house money.",false,"Cocktails and Mocktails Manual v2026/01, drink presentation standards; AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, spirits (30 ML)",null,"live","David","2026-10-16",null,1],["drk-bar-standards-0002","drinks","bar-standards",2,["bar","server"],"mcq","How much is a glass of wine?",null,["150 ml","125 ml","175 ml","200 ml"],["150 ml"],"Wine and sparkling wine by the glass is 150 ml.","Guests compare glass and bottle; know the measure.",false,"Cocktails and Mocktails Manual v2026/01, drink presentation standards; AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, wines (150 ML / 750 ML)",null,"live","David","2026-10-16",null,1],["drk-bar-standards-0003","drinks","bar-standards",2,["bar"],"mcq","What's the rule on pouring above the measure?",null,["Over-pouring is not accepted","Allowed for regulars","Allowed if the guest asks","Up to 5 ml is fine"],["Over-pouring is not accepted"],"Over-pouring is not accepted: every recipe is tested, and a drink made by one bartender must be made exactly the same by all others.","Consistency is what guests expect every time.",false,"Cocktails and Mocktails Manual v2026/01, drink presentation standards",null,"live","David","2026-10-16",null,1],["drk-bar-standards-0004","drinks","bar-standards",2,["bar","server","barista"],"multi","Glassware rules: what's right? Pick all that apply.",null,["Use the proper glass for each drink","Always use a tong for ice","Check glasses aren't cracked or chipped","Put breakage in the specific bin","Put breakage in the general bin"],["Use the proper glass for each drink","Always use a tong for ice","Check glasses aren't cracked or chipped","Put breakage in the specific bin"],"Use the proper, sparkling-clean glass, check for cracks and chips, always use a tong for ice, and put breakage in the specific bin.","A chip or a shard of glass can injure a guest.",false,"Cocktails and Mocktails Manual v2026/01, glassware rules",null,"live","David","2026-10-16",null,1],["drk-bar-standards-0005","drinks","bar-standards",2,["bar"],"multi","Bar set-up before service: which are non-negotiable? Pick all that apply.",null,["Ice, garnishes and syrups ready","Glassware polished and stacked","Spirits at par level","Cocktail tools clean and in position","Cocktails pre-mixed in jugs"],["Ice, garnishes and syrups ready","Glassware polished and stacked","Spirits at par level","Cocktail tools clean and in position"],"Bar mise en place: ice, garnishes and syrups, glassware polished and stacked, spirits at par, tools clean and in position. No exceptions.","A ready bar keeps cocktails inside the 8-minute standard.",false,"Operations Manual v2026/01, bar setup",null,"live","David","2026-10-16",null,1],["drk-spirits-wine-basics-0006","drinks","spirits-wine-basics",2,["bar","server"],"mcq","Tequila is made from which plant?",null,["Blue agave","Sugar cane","Juniper","Rye"],["Blue agave"],"Tequila is made from the blue agave plant of Mexico. Rum is made from sugar cane; gin from juniper berries.","Guests ask; a confident answer builds trust.",false,"Cocktails and Mocktails Manual v2026/01, know your spirits",null,"live","David","2026-10-16",null,1],["drk-spirits-wine-basics-0007","drinks","spirits-wine-basics",2,["bar","server"],"mcq","Which spirit is made from sugar cane?",null,["Rum","Vodka","Tequila","Gin"],["Rum"],"Rum is made from sugar cane, from clear to dark brown.","Helps you guide a guest to a style they'll like.",false,"Cocktails and Mocktails Manual v2026/01, know your spirits",null,"live","David","2026-10-16",null,1],["drk-spirits-wine-basics-0008","drinks","spirits-wine-basics",2,["bar","server"],"mcq","Which brandy may be called Cognac?",null,["Only brandy from the Cognac region of France","Any French brandy","Any aged grape brandy","Brandy aged over 10 years"],["Only brandy from the Cognac region of France"],"Only brandy from the Cognac region of France may be called Cognac. It's most often an after-dinner drink, neat in a snifter or on the rocks.","Good for suggesting a digestif with confidence.",false,"Cocktails and Mocktails Manual v2026/01, know your spirits",null,"live","David","2026-10-16",null,1],["drk-spirits-wine-basics-0009","drinks","spirits-wine-basics",2,["bar","server"],"mcq","What makes a sparkling wine a Champagne?",null,["It's made in France","It's made in Italy","It's served in a flute","It's always rosé"],["It's made in France"],"Champagne is made in France; any other type is sparkling wine. Our Louis Roederer Brut NV is a Champagne; the Da Luca Prosecco is an Italian sparkling wine.","Calling things by the right name matters to guests who are celebrating.",false,"Cocktails and Mocktails Manual v2026/01, Champagne; AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, sparkling and Champagne",null,"live","David","2026-10-16",null,1],["drk-spirits-wine-basics-0010","drinks","spirits-wine-basics",2,["bar","server"],"mcq","Where is the Matua Valley Sauvignon Blanc from?",null,["New Zealand","France","Chile","South Africa"],["New Zealand"],"Matua Valley Sauvignon Blanc is from New Zealand.","Guests often choose wine by country.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, white wine",null,"live","David","2026-10-16",null,1],["drk-spirits-wine-basics-0011","drinks","spirits-wine-basics",2,["bar","server"],"mcq","Which of our red wines is from Spain?",null,["Cune Rioja Crianza","La Linda Malbec","Kadette Cape Blend","Merlot Bio Bio"],["Cune Rioja Crianza"],"Cune Rioja Crianza is Spanish. La Linda Malbec is from Argentina, Kadette Cape Blend from South Africa and Merlot Bio Bio from Italy.","Matching a guest's favourite country is an easy recommendation.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, red wine",null,"live","David","2026-10-16",null,1],["drk-spirits-wine-basics-0012","drinks","spirits-wine-basics",2,["bar","server"],"mcq","Which of these is our Champagne rosé?",null,["Laurent-Perrier Cuvée Rosé Brut NV","Da Luca Sparkling Rosé","Colombelle Rose","Eau de Provence Rose"],["Laurent-Perrier Cuvée Rosé Brut NV"],"Laurent-Perrier Cuvée Rosé Brut NV is from France. Da Luca Sparkling Rosé is Italian; Colombelle and Eau de Provence are still rosés.","Celebrating guests often ask for pink Champagne.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, sparkling and Champagne; rosé",null,"live","David","2026-10-16",null,1],["drk-beer-0013","drinks","beer",2,["bar","server"],"mcq","Which draught beer is a light-bodied Belgian wheat beer?",null,["Hoegaarden","Stella Artois","Leffe Brune","Guinness"],["Hoegaarden"],"Hoegaarden (Belgium, 4.9%) is a light-bodied wheat beer with orange zest, spices and coriander.","Wheat beer fans will look for it.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, draught beer",null,"live","David","2026-10-16",null,1],["drk-beer-0014","drinks","beer",2,["bar","server"],"mcq","A guest wants a dark Belgian abbey beer on draught. Which do you suggest?",null,["Leffe Brune","Leffe Blonde","Hoegaarden","Kronenbourg 1664 Blanc"],["Leffe Brune"],"Leffe Brune (Belgium, 6.5%) is an authentic abbey beer with darkly roasted malt: vanilla, cloves and chocolate.","It's also the beer our Belgian beef stew is braised in.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, draught beer; Meat Specials",null,"live","David","2026-10-16",null,1],["drk-beer-0015","drinks","beer",2,["bar","server"],"mcq","What's the strength of Duvel?",null,["8.5%","5%","6.6%","4.9%"],["8.5%"],"Duvel (Belgium, 8.5%) is \"Belgian beer royalty\", devilishly strong.","Guests should know it's much stronger than a lager.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, bottled beer",null,"live","David","2026-10-16",null,1],["drk-beer-0016","drinks","beer",2,["bar","server"],"mcq","Which beer tastes of tart cherries?",null,["Liefmans Kriek-Brut","Duvel","Magners Dark Fruits","Somersby"],["Liefmans Kriek-Brut"],"Liefmans Kriek-Brut (Belgium, 6.2%) has tart cherries and a refreshing, lightly sweet finish.","A great suggestion for guests who don't usually like beer.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, bottled beer",null,"live","David","2026-10-16",null,1],["drk-beer-0017","drinks","beer",2,["bar","server"],"mcq","Which draught is a typical Belgian blonde ale?",null,["Leffe Blonde","Stella Artois","Carlsberg","Peroni Nastro Azzurro"],["Leffe Blonde"],"Leffe Blonde (Belgium, 6.6%) is a typical, perfectly balanced Belgian blonde: raisin, banana, aromatic herbs.","Belgian beer is part of our house story.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, draught beer",null,"live","David","2026-10-16",null,1],["drk-beer-0018","drinks","beer",2,["bar","server"],"multi","Which alcohol-free beers do we serve? Pick all that apply.",null,["Peroni 0.0%","Corona Cero 0.0%","Guinness 0.0%","Fly Craft 0.0%","Stella Artois 0.0%"],["Peroni 0.0%","Corona Cero 0.0%","Guinness 0.0%","Fly Craft 0.0%"],"Peroni 0.0%, Corona Cero 0.0%, Guinness 0.0% and Fly Craft 0.0% from the UAE.","Every guest should get a good drink, with or without alcohol.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, non-alcoholic beer",null,"live","David","2026-10-16",null,1],["drk-cocktails-0019","drinks","cocktails",2,["bar","server"],"multi","What goes into a Negroni? Pick all that apply.",null,["Gin","Campari","Sweet vermouth","Vodka","Soda"],["Gin","Campari","Sweet vermouth"],"A Negroni is gin, Campari and sweet vermouth, three equal parts, in a vintage rock glass with orange peel.","An iconic classic many guests order by name.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, cocktails; Cocktails and Mocktails Manual v2026/01, classic cocktails",null,"live","David","2026-10-16",null,1],["drk-cocktails-0020","drinks","cocktails",2,["bar"],"mcq","Which glass and garnish for an Aperol Spritz?",null,["Red wine glass, dry orange","Highball, lime wedge","Coupe, orange peel","Rock glass, mint sprig"],["Red wine glass, dry orange"],"Aperol Spritz: Aperol, sparkling wine and soda, served in a red wine glass with dry orange.","The right glass and garnish are part of the drink.",false,"Cocktails and Mocktails Manual v2026/01, signature cocktails; AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, cocktails",null,"live","David","2026-10-16",null,1],["drk-cocktails-0021","drinks","cocktails",2,["bar"],"mcq","How is a Margarita served?",null,["Shaken, fine strained, salt-rim glass, lime wedge","Stirred, on the rocks, orange peel","Built in a highball, topped with soda","Blended, with a sugar rim"],["Shaken, fine strained, salt-rim glass, lime wedge"],"Margarita: tequila, orange liqueur, fresh lime and simple syrup, shaken and fine strained into a salt-rimmed cocktail glass with a lime wedge.","Getting the serve right is what makes it ours.",false,"Cocktails and Mocktails Manual v2026/01, classic cocktails; AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, cocktails",null,"live","David","2026-10-16",null,1],["drk-cocktails-0022","drinks","cocktails",2,["bar","server"],"mcq","What's in our Espresso Martini?",null,["Vodka, espresso, coffee liqueur, vanilla syrup","Rum, espresso, cream","Baileys, espresso, vodka","Tequila, espresso, agave"],["Vodka, espresso, coffee liqueur, vanilla syrup"],"Espresso Martini: vodka, espresso, coffee liqueur and vanilla syrup, in a Marie Antoinette coupe with coffee beans.","A popular after-dinner suggestion.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, cocktails; Cocktails and Mocktails Manual v2026/01, coffee and digestifs",null,"live","David","2026-10-16",null,1],["drk-cocktails-0023","drinks","cocktails",2,["bar","server"],"mcq","Which of our signature cocktails has dill and cucumber?",null,["Dill or Not Deal","Black Forest","Maison Orchard","Spicy José"],["Dill or Not Deal"],"Dill or Not Deal: gin, elderflower, cucumber, dill leaf, lemon juice, simple syrup and egg whites. It's our own signature.","Signatures are drinks guests can only get here.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, signature cocktails; Cocktails and Mocktails Manual v2026/01, signature cocktails",null,"live","David","2026-10-16",null,1],["drk-cocktails-0024","drinks","cocktails",2,["bar","server"],"mcq","Which signature cocktail lists egg whites?",null,["Dill or Not Deal","Maison Home-Made Mule","Passion in Rum","El Chapo"],["Dill or Not Deal"],"Dill or Not Deal lists egg whites. Egg is one of the 14 major allergens.","A guest with an egg allergy may not expect egg in a cocktail.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, signature cocktails","[TO CONFIRM] Drafted from the menu's listed ingredients only. Gerard to check.","review","David","2026-10-16",null,1],["drk-cocktails-0025","drinks","cocktails",2,["bar","server"],"mcq","What is the Nutty Espresso Martini garnished with?",null,["Roasted, crushed pistachios and almonds","Coffee beans","Grated dark chocolate","Star anise"],["Roasted, crushed pistachios and almonds"],"Nutty Espresso Martini: vodka, Amaretto Disaronno, Kahlua, espresso and pistachio syrup, with crushed pistachios and almonds.","It contains nuts, so it matters for any guest with a nut allergy.",true,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, autumn espresso martini","[TO CONFIRM] Drafted from the menu's listed ingredients only. The menu doesn't mark it (N). Gerard to check.","review","David","2026-10-16",null,1],["drk-cocktails-0026","drinks","cocktails",2,["bar","server"],"mcq","Which autumn espresso martini is served in a lightly smoked cloche?",null,["Oaxaca Espresso Martini","Tiramisu Espresso Martini","Spiced Espresso Martini","Nutty Espresso Martini"],["Oaxaca Espresso Martini"],"Oaxaca: Patron XO Café, 400 Conejos mezcal, espresso, agave syrup and grated Mexican dark chocolate, in a lightly smoked cloche.","A bit of theatre to describe at the table.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, autumn espresso martini",null,"live","David","2026-10-16",null,1],["drk-cocktails-0027","drinks","cocktails",2,["bar","server"],"mcq","A sangria pitcher is served in which jug?",null,["ARAS jug, 1.5 L","Carafe, 1 L","Glass jug, 2 L","Wine decanter"],["ARAS jug, 1.5 L"],"All sharing pitchers are served in the ARAS jug, 1.5 L.","Guests ask how many glasses a pitcher pours.",false,"Cocktails and Mocktails Manual v2026/01, sharing pitchers and sangria",null,"live","David","2026-10-16",null,1],["drk-cocktails-0028","drinks","cocktails",2,["bar","server"],"multi","What's in our Red Sangria? Pick all that apply.",null,["Red wine","Rum","Orange liqueur","Cranberry juice","Gin","Prosecco"],["Red wine","Rum","Orange liqueur","Cranberry juice"],"Red Sangria: red wine, rum, orange liqueur, grenadine, mixed fruits, orange juice, cranberry juice and soda.","Guests are often surprised it includes rum.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, sharing pitchers; Cocktails and Mocktails Manual v2026/01, sharing pitchers",null,"live","David","2026-10-16",null,1],["drk-cocktails-0029","drinks","cocktails",2,["bar","server"],"mcq","Which premium G&T is garnished with cucumber?",null,["Hendrick's","Gin Mare","Roku","Tanqueray 10 Citrus"],["Hendrick's"],"Hendrick's is served with cucumber. Gin Mare comes with basil, rosemary and olives; Roku with fresh ginger slices.","The garnish shows off each gin's flavour.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, G&T speciality; Cocktails and Mocktails Manual v2026/01, gin and tonic selection",null,"live","David","2026-10-16",null,1],["drk-mocktails-soft-0030","drinks","mocktails-soft",2,["bar","server"],"mcq","A guest who's driving liked the look of the Hugo. What do you suggest?",null,["Drivers Hugo","Virgin Mojito","Mint Lemonade","Apple Granita"],["Drivers Hugo"],"Drivers Hugo is the alcohol-free Hugo: elderflower, mint, lemon juice and soda.","Everyone at the table can join the round.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, mocktails; Cocktails and Mocktails Manual v2026/01, mocktails",null,"live","David","2026-10-16",null,1],["drk-mocktails-soft-0031","drinks","mocktails-soft",2,["bar","server"],"mcq","What is a Simple Mary?",null,["An alcohol-free Bloody Mary","A plain tonic water","A virgin mojito","An iced tea"],["An alcohol-free Bloody Mary"],"Simple Mary is the alcohol-free Bloody Mary: tomato juice, lemon, salt, pepper, Tabasco, Worcestershire, celery and olive.","Spice can be adjusted to the guest's taste.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, mocktails; Cocktails and Mocktails Manual v2026/01, mocktails",null,"live","David","2026-10-16",null,1],["drk-mocktails-soft-0032","drinks","mocktails-soft",2,["bar","server"],"multi","Which flavours do our Virgin Mojitos come in? Pick all that apply.",null,["Simple","Peach","Strawberry","Passion Fruit","Mango"],["Simple","Peach","Strawberry","Passion Fruit"],"Virgin Mojitos, like our iced teas, come Simple, Peach, Strawberry or Passion Fruit.","Offering the flavours makes it easy to choose.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, mocktails",null,"live","David","2026-10-16",null,1],["drk-mocktails-soft-0033","drinks","mocktails-soft",2,["bar","server","host"],"mcq","A table asks for water. What can you offer?",null,["Filtered still with unlimited refills, or Eira still or sparkling","Tap water only","Eira sparkling only","Water comes free with food"],["Filtered still with unlimited refills, or Eira still or sparkling"],"We serve filtered still water with unlimited refills, and Eira still or sparkling in 0.4 L or 1 L.","Water is the first drink most tables order.",false,"AR lunch and dinner menu, 20260922_MM-AR-LUNCHDINNER39, water",null,"live","David","2026-10-16",null,1],["drk-coffee-tea-0034","drinks","coffee-tea",2,["barista","server","bar"],"multi","Which green teas are on the menu? Pick all that apply.",null,["Matcha Green Tea","Morrocan Mint","Jasmine","Mao Feng","Earl Grey"],["Matcha Green Tea","Morrocan Mint","Jasmine","Mao Feng"],"Our bio-organic green teas are Matcha, Morrocan Mint, Jasmine and Mao Feng. Earl Grey is a black tea.","Tea drinkers like to hear the choice.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, bio-organic teas",null,"live","David","2026-10-16",null,1],["drk-coffee-tea-0035","drinks","coffee-tea",2,["barista","server","bar"],"mcq","Which of these is a cold coffee on our menu?",null,["Cold Brew Tonic","Flat White","Cortado","Macchiato"],["Cold Brew Tonic"],"Our cold coffees include Cream and Caramel Cold Brew, Cold Brew Tonic, Espresso Tonico, Iced Spanish Latte and Cold Drip Coffee.","In the Dubai heat, many guests want their coffee cold.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, hot beverages",null,"live","David","2026-10-16",null,1],["drk-coffee-tea-0036","drinks","coffee-tea",2,["barista","server","bar"],"mcq","A guest wants a juice that isn't on the list. What can you offer?",null,["\"Mix Your Own\" from our fresh juices","Only the juices listed","A smoothie instead","A soft drink"],["\"Mix Your Own\" from our fresh juices"],"Guests can mix their own from green apple, red apple, orange, grapefruit, carrot, watermelon, cucumber, celery, lemon, pineapple, ginger and beetroot.","A made-to-order juice is a lovely yes.",false,"AR breakfast menu, 20260914_MM-AR-BREAKFAST53, juices",null,"live","David","2026-10-16",null,1],["drk-coffee-tea-0037","drinks","coffee-tea",2,["barista","server","bar"],"mcq","What follows every coffee or hot drink order?",null,["A check back, then offer the next one","Nothing, it's a small order","The bill","A dessert menu only"],["A check back, then offer the next one"],"Follow up after every coffee or hot drink, and offer the next one.","A guest who isn't enjoying their drink won't order a second.",false,"Service Training Program v2026/01, coffee upselling; Operations Manual v2026/01, coffee check-back",null,"live","David","2026-10-16",null,1]]$cards$::jsonb) as e
on conflict (id) do nothing;

update public.card_versions set saved_by = 'Phase 0 drafts' where saved_by = 'System' and version = 1;
update public.audit_log set actor = 'Phase 0 drafts' where actor = 'System' and action = 'card_created';

select status, is_allergen, count(*) from public.cards group by 1, 2 order by 1, 2;
